"""Shipping zone, cost, and oversize helpers."""


def shipping_zone(country_code):
    """Return the shipping zone for a country code.

    DE -> 1, FR or NL -> 2, anything else -> 3.
    """
    if country_code == "DE":
        return 1
    if country_code in ("FR", "NL"):
        return 2
    return 3


_BASE_BY_ZONE = {1: 4.5, 2: 9.0, 3: 20.0}


def shipping_cost(weight_kg, zone):
    """Return base + 1.5 * weight_kg, rounded to 2 decimals.

    Base is 4.5 for zone 1, 9.0 for zone 2, 20.0 for zone 3.
    """
    base = _BASE_BY_ZONE[zone]
    return round(base + 1.5 * weight_kg, 2)


def is_oversize(l, w, h):
    """Return True if any dimension exceeds 120 or l + w + h exceeds 300."""
    if l > 120 or w > 120 or h > 120:
        return True
    return l + w + h > 300

import re

_SKU_RE = re.compile(r"([A-Z]{2,4})-([0-9]{4})-([A-Z])")


def bulk_discount(qty):
    if qty >= 100:
        return 0.25
    if qty >= 20:
        return 0.08
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


def parse_sku(s):
    if not isinstance(s, str):
        raise ValueError(f"invalid SKU: {s!r}")
    m = _SKU_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid SKU: {s!r}")
    cat, num, var = m.groups()
    return {"category": cat, "number": int(num), "variant": var}

